def closestRotated(nums, x):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    s = lo
    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[(s + mid) % n] < x:
            lo = mid + 1
        else:
            hi = mid
    if lo == 0:
        return nums[s]
    if lo == n:
        return nums[(s + n - 1) % n]
    below = nums[(s + lo - 1) % n]
    above = nums[(s + lo) % n]
    return below if x - below <= above - x else above
